// Gowin synthesis file list for the Tang Mega 138K Pro speaker board top.
// Import this list together with tang_mega_138k_pro.cst and .sdc into a Gowin
// project for GW5AST-LV138FPG676AES (Device Version B, FPG676).
//
// The synthesis TOP is board_top (board_top.sv), which wraps top.sv and overrides
// COEFF_FILE/INDEX_FILE with ABSOLUTE ROM paths so $readmemh always finds the
// images regardless of the tool's working directory (a relative path silently
// failed with WARN EX3988 and let the engine constant-fold away).
//
// The two PLL IP files are generated by the user with the Gowin IP Core
// Generator.  They are intentionally absent here: if they are missing, synthesis
// must fail rather than silently use a behavioural model.  The test-only models
// under sim/audio_helpers/ are NEVER listed here.
//
// Paths are relative to the repository root; run Gowin from the repository root
// (build.sh / gowin_build.tcl do).

// board wrapper
rtl/platform/tang_mega_138k_pro/board_top.sv
rtl/platform/tang_mega_138k_pro/top.sv
rtl/platform/tang_mega_138k_pro/clock_reset.sv
rtl/platform/tang_mega_138k_pro/board_audio_core.sv

// generated Gowin PLL IP (must exist before synthesis)
rtl/platform/tang_mega_138k_pro/ip/pll_init.v
rtl/platform/tang_mega_138k_pro/ip/pll_core_100m/gowin_pll_core_100m.v
rtl/platform/tang_mega_138k_pro/ip/pll_core_100m/gowin_pll_core_100m_mod.v
rtl/platform/tang_mega_138k_pro/ip/pll_audio_12m5/gowin_pll_audio_12m5.v
rtl/platform/tang_mega_138k_pro/ip/pll_audio_12m5/gowin_pll_audio_12m5_mod.v

// audio datapath
rtl/audio/audio_async_fifo.sv
rtl/audio/pt8211_tx.sv
rtl/audio/i2s_amp_tx.sv
rtl/audio/i2s_mic_rx.sv
rtl/audio/audio_transport.sv
rtl/audio/song_player.sv
rtl/audio/audio_demo_core.sv

// modal engine (2B/2C) + body filter
rtl/core/coeff_loader.sv
rtl/core/poly_modal_lane.sv
rtl/core/modal_poly_bank.sv
rtl/core/modal_engine.sv
rtl/core/body_filter.sv
